public boolean shouldPrintMessage(int timestamp, String message) {
    if (timestamp < 0 || message == null || message.isEmpty()) {
        return false;
    }
    // Assuming we have a way to store the last print time for each message
    // For simplicity, we'll use a HashMap to store this information
    // In a real-world scenario, you might use a more persistent storage
    HashMap<String, Integer> lastPrintTimes = new HashMap<>();

    if (!lastPrintTimes.containsKey(message)) {
        lastPrintTimes.put(message, timestamp);
        return true;
    } else {
        int lastPrintTime = lastPrintTimes.get(message);
        if (timestamp - lastPrintTime >= 10) {
            lastPrintTimes.put(message, timestamp);
            return true;
        }
    }
    return false;
}

