boolean function(int val) {
    if (val < 0 || val >= size()) {
        return false;
    }

    int bucketIndex = val / 32;
    int bitIndex = val % 32;
    long bucket = buckets[bucketIndex];

    if ((bucket & (1L << bitIndex)) != 0) {
        buckets[bucketIndex] ^= (1L << bitIndex);
        size--;
        return true;
    }

    return false;
}

