protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type != java.lang.Character.class) {
        throw new IllegalArgumentException("Unsupported type for conversion: " + type);
    }
    if (value == null) {
        return null;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof java.lang.String) {
        String strValue = (java.lang.String) value;
        if (strValue.length() == 1) {
            return strValue.charAt(0);
        } else {
            throw new IllegalArgumentException("String value must have exactly one character");
        }
    }
    if (value instanceof Number) {
        Number numValue = (Number) value;
        int intValue = numValue.intValue();
        if (intValue >= Character.MIN_VALUE && intValue <= Character.MAX_VALUE) {
            return (char) intValue;
        } else {
            throw new IllegalArgumentException("Number value out of character range");
        }
    }
    throw new Exception("Unsupported conversion from type: " + value.getClass());
}

