public static long factorial(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be a non-negative integer.");
    }
    if (n == 0 || n == 1) {
        return 1;
    }
    long result = 1;
    for (int i = 2; i <= n; i++) {
        result *= i;
        if (result < 0) {
            throw new ArithmeticException("Factorial result is too large to be stored in a long.");
        }
    }
    return result;
}

