        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    Set<String> vertices = resultMap.keySet();
    if (vertices.size() < 2) {
        throw new IllegalArgumentException("At least two vertices are required to form a complete bipartite graph");
    }

    Iterator<String> iterator = vertices.iterator();
    String vertex1 = iterator.next();
    String vertex2 = iterator.next();
    V v1 = resultMap.get(vertex1);
    V v2 = resultMap.get(vertex2);

    // Add vertex1 and vertex2 to the target graph
    target.addNode(v1);
    target.addNode(v2);

    // Add an edge between vertex1 and vertex2
    target.addEdge(v1, v2);
}

