    List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();
    for (int v = 0; v < V; v++) {
        for (int w = v + 1; w < V; w++) {
            if (adj[v][w] != null) {
                E edge = adj[v][w].getEdge();
                List<Pair<Integer, Integer>> separators = new ArrayList<>();
                for (int u : adj[v]) {
                    if (u != v && u != w && adj[w][u] != null) {
                        int u1 = v, u2 = w;
                        if (u1 > u2) {
                            int temp = u1;
                            u1 = u2;
                            u2 = temp;
                        }
                        separators.add(Pair.of(u1, u2));
                    }
                }
                globalSeparatorList.add(Pair.of(separators, edge));
            }
        }
    }
    return globalSeparatorList;
}

