    if (end - start < FETCH_DATA_DURATION) {
        return Collections.singletonList(new TimeRange(start, end));
    }

    List<TimeRange> timeRanges = new ArrayList<>();
    long currentTime = start;

    while (currentTime < end) {
        long nextTime = currentTime + FETCH_DATA_DURATION;
        if (nextTime > end) {
            nextTime = end;
        }
        timeRanges.add(new TimeRange(currentTime, nextTime));
        currentTime = nextTime;
    }

    return timeRanges;
}

