        throw new IllegalArgumentException("Index is out of bounds");
    }
    if (len < 0 || len > str.length() - index) {
        throw new IllegalArgumentException("Length is out of bounds");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
